/* ── Local form capture ───────────────────────────────────────────
   Completed forms stay inside this app's configured Supabase project.
   RLS on public.form_submissions limits rows to the signed-in user/admin.
─────────────────────────────────────────────────────────────────── */
function mcCapture(formType, details) {
  try {
    void supabase.auth.getUser().then(({ data }) => {
      if (!data?.user) return;
      return supabase.from("form_submissions").insert({
        user_id: data.user.id,
        form_type: formType,
        details: details || {},
      });
    }).catch(() => { });
  } catch (e) { }
}
