const AREAS = ["Koregaon Park", "Viman Nagar", "Hinjewadi", "Shivaji Nagar", "Camp", "Aundh", "Kothrud", "Deccan Gymkhana", "Wakad", "Baner", "Bhosari", "Pimpri", "Chinchwad", "Nigdi", "Akurdi", "Chikhali", "Moshi", "Ravet", "Tathawade", "Punawale"];
