// Real enrolled medicos only — sourced from LIVE_BY_VIEW.medico (seeded via
// Supabase profiles). No fake/generated doctor names anywhere in the UI.
// If a medico's profile.specialty matches (case-insensitive substring on
// spec.name / spec.shortName), they show up in that specialty's list;
// medicos with no specialty set are shown in every list (opt-in).
function _liveMedicoRoster() {
  const rows = (typeof LIVE_BY_VIEW !== "undefined" && LIVE_BY_VIEW.medico) || [];
  return rows.filter(p => p && p.name && p.userId);
}
// Preferred-doctor lists show only doctors who have actually treated a patient.
// PATIENTS_SERVED is filled from provider_patient_counts(); until that function is
// installed it stays null and the list is not filtered (nothing breaks).
let PATIENTS_SERVED = null;
function _hasTreatedPatients(m) {
  return PATIENTS_SERVED == null || (PATIENTS_SERVED[m.userId] || 0) > 0;
}
// Non-doctor roles that must never appear in a specialty doctor panel,
// matched against the profile's display name AND specialty field.
const _NON_DOCTOR_ROLES = ["nurse", "paramedic", "technician", "therapist", "pharmacist", "receptionist", "coordinator", "ward boy", "attender"];

function _medicoMatchesSpec(medico, spec) {
  if (!spec) return true;
  // Exclude non-doctor roles regardless of specialty field value
  const nameLower  = (medico.name     || "").toLowerCase().trim();
  const specField  = (medico.specialty || "").toLowerCase().trim();
  if (_NON_DOCTOR_ROLES.some(r =>
    nameLower === r || nameLower.startsWith(r + " ") || specField === r
  )) return false;
  // No specialty on file → show in all specialty panels as a general-fallback doctor
  if (!specField) return true;
  const targets = [spec.name, spec.shortName, spec.id].filter(Boolean).map(s => String(s).toLowerCase());
  return targets.some(t => specField.includes(t) || t.includes(specField));
}
function _stableSeed(str) {
  return String(str || "x").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
}

// Deterministic small list of named doctors for a speciality (for the inline dropdown)
function docsForSpec(spec) {
  if (!spec) return [];
  const roster = _liveMedicoRoster().filter(m => _medicoMatchesSpec(m, spec));
  return roster.map((m, i) => {
    const seed = _stableSeed(m.userId || m.name) + i;
    return {
      id: (spec.id || "spec") + "_" + m.userId,
      userId: m.userId,
      name: m.name,
      rating: (4.4 + (seed % 6) / 10).toFixed(1),
      exp: 4 + (seed % 20),
      fee: (spec.base || 500) + (i * 100),
      nextSlot: ["Now", "in 20 min", "in 1 hr", "Today 5 PM"][seed % 4],
      pref: i === 0,
    };
  });
}
const rnd = (a, b) => a + Math.random() * (b - a);
const pick = arr => arr[Math.floor(Math.random() * arr.length)];

// Panel of profile-able doctors for a specialty — used by the patient's
// elective doctor-selection step and the My/Preferred manager. Only real
// enrolled medicos are shown; ratings/qualifications are derived from stable
// per-medico seeds so display stays consistent.
const QUALS = ["MBBS, MD", "MBBS, MS", "MBBS, DNB", "MBBS, MD, DM", "MBBS, MS, MCh", "MBBS, DGO"];
function panelDoctorsForSpec(spec) {
  if (!spec) return [];
  const roster = _liveMedicoRoster().filter(m => _medicoMatchesSpec(m, spec) && _hasTreatedPatients(m));
  const list = roster.map((m, i) => {
    const seed = _stableSeed(m.userId || m.name);
    const patientRating = +(4.3 + ((seed + i * 3) % 7) / 10).toFixed(1);
    const hospitalRating = +(4.2 + ((seed + i * 5) % 8) / 10).toFixed(1);
    const professionalScore = Math.max(72, Math.min(99, Math.round(((patientRating / 5) * 55) + ((hospitalRating / 5) * 35) + 10 - (i * 1.5))));
    return {
      id: (spec.id || "spec") + "_panel_" + m.userId,
      userId: m.userId,
      name: m.name,
      qualification: QUALS[seed % QUALS.length],
      exp: 5 + (seed % 19),
      patientRating, hospitalRating, professionalScore,
      reviews: 40 + (seed % 260),
      fee: (spec.base || 500) + (i * 100),
      nextSlot: ["Today 5 PM", "Tomorrow 10 AM", "Today 7 PM", "In 2 days", "Tomorrow 4 PM"][seed % 5],
      bio: `Experienced ${(spec.name || "specialist").toLowerCase()} focused on patient-first, evidence-based care.`,
    };
  });
  return list.sort((a, b) => b.professionalScore - a.professionalScore);
}

/* Signed-in user identity. Populated from localStorage by /auth after sign-in
   (mc_user_name / mc_user_role). No hardcoded doctor names. */
function _pickMedico() {
  try {
    if (typeof window === "undefined") return { name: "You", rating: 0, exp: 0 };
    const name = window.localStorage.getItem("mc_user_name") || "You";
    return { name, rating: 0, exp: 0 };
  } catch { return { name: "You", rating: 0, exp: 0 }; }
}
const _M = _pickMedico();
const YOU = { id: "you", name: _M.name, rating: _M.rating, exp: _M.exp, distanceKm: 1.8, etaMin: 8, isYou: true };

function buildFare(spec, emergency) {
  const base = spec.base || 800, conv = 99, dist = Math.round(rnd(40, 140));
  const surge = emergency ? Math.round(base * 0.2) : 0;
  return { base, convenience: conv, distance: dist, surcharge: surge, total: base + conv + dist + surge };
}
function providerPrefix(kind) {
  return kind === "nurse" ? "Sr. " : kind === "rmo" ? "Dr. " : kind === "tech" ? "Tech " : "Dr. ";
}
// ── Live directory of enrolled + active accounts ──────────────────────
// Populated from Supabase on module load and refreshed before every broadcast.
// Keyed by the module the account uses (medico / diagnostic / labs / pharmacy /
// ambulance / hub / seva). Used by the patient-side flows to show — Uber-style
// — only real accounts of the requested category that are actually online.
const ONLINE_WINDOW_MS = 5 * 60_000; // "live" = heartbeat within last 5 minutes
export const LIVE_BY_VIEW = {
  medico: [],
  diagnostic: [],
  labs: [],
  pharmacy: [],
  ambulance: [],
  hub: [],
  seva: [],
};
async function refreshLiveProviders() {
  try {
    const { data: profs } = await supabase
      .from("profiles")
      .select("id, full_name, specialty, view, last_seen_at, lat, lng");
    const now = Date.now();
    for (const k of Object.keys(LIVE_BY_VIEW)) LIVE_BY_VIEW[k] = [];
    (profs || []).forEach((p, i) => {
      const v = p.view;
      if (!v || !(v in LIVE_BY_VIEW)) return;
      const seen = p.last_seen_at ? new Date(p.last_seen_at).getTime() : 0;
      const online = seen && (now - seen) < ONLINE_WINDOW_MS;
      LIVE_BY_VIEW[v].push({
        id: "live_" + p.id,
        userId: p.id,
        name: p.full_name || "Provider",
        specialty: p.specialty || null,
        view: v,
        lat: p.lat, lng: p.lng,
        online: !!online,
        rating: 4.8,
        exp: 5,
        distanceKm: 0.6 + i * 0.4,
        etaMin: 5 + i * 2,
        isLive: true,
      });
    });
    try {
      const { data: counts, error: countErr } = await supabase.rpc("provider_patient_counts");
      if (!countErr && Array.isArray(counts)) {
        const map = {};
        counts.forEach(r => { map[r.provider_id] = Number(r.patients) || 0; });
        PATIENTS_SERVED = map;
      }
    } catch { /* function not installed yet: show everyone */ }
    // Prefer online accounts first in every bucket
    for (const k of Object.keys(LIVE_BY_VIEW)) {
      LIVE_BY_VIEW[k].sort((a, b) => Number(b.online) - Number(a.online));
    }
  } catch { /* keep previous cache */ }
}
// Only "live" (online-in-last-5-min) accounts for a given view
function liveOnlineByView(view) {
  return (LIVE_BY_VIEW[view] || []).filter(p => p.online);
}
// prime once at module load (may return nothing if user is not yet authed)
refreshLiveProviders();
// Re-fetch as soon as a session is established — the RLS policy on profiles
// requires auth, so the module-load fetch above returns [] for unauthenticated
// visitors. We need to refresh again after login so the doctor panel is populated.
supabase.auth.onAuthStateChange((event) => {
  if (event === "SIGNED_IN") refreshLiveProviders();
});

// Heartbeat: while any patient/medico session is open, mark the current
// account as online so other users' broadcasts include them. Fire-and-forget.
async function heartbeatOnce() {
  try {
    const { data: sess } = await supabase.auth.getSession();
    const uid = sess.session?.user?.id;
    if (!uid) return;
    await supabase.from("profiles")
      .update({ last_seen_at: new Date().toISOString() })
      .eq("id", uid);
  } catch { /* ignore */ }
}
if (typeof window !== "undefined") {
  heartbeatOnce();
  setInterval(heartbeatOnce, 60_000); // every minute
}

function buildHubCandidates(hub, emergency, kind) {
  // Only real logged-in medicos can actually accept a broadcast (via the live
  // care_requests subscription in DoctorApp). We still surface every registered
  // provider on the radar so the patient sees who is on the platform.
  const px = providerPrefix(kind);
  const you = kind && kind !== "doctor"
    ? { id: "you", name: px + "—", rating: 0, exp: 0, distanceKm: 1.2, etaMin: 9, notifyAt: 400, acceptAt: 999999, area: hub?.area, isYou: true }
    : { ...YOU, notifyAt: 400, acceptAt: 999999, area: hub?.area };
  const pool = (kind === "doctor" || !kind)
    ? liveOnlineByView("medico")
    : (kind === "nurse" || kind === "rmo") ? liveOnlineByView("medico")
      : (kind === "tech") ? liveOnlineByView("diagnostic")
        : [];
  const live = pool
    .filter(p => p.name !== YOU.name) // exclude self
    .map((p, i) => ({
      ...p,
      area: hub?.area,
      notifyAt: 500 + i * 400,
      acceptAt: 999999, // never auto-accept — only the real medico can accept
    }));
  return [you, ...live];
}

function deterministicDoctorCandidate(name, spec, slot = "my_doctor") {
  if (!name) return null;
  const seed = String(name).split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  return {
    id: slot + "_" + String(name).toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, ""),
    name,
    rating: +(4.6 + (seed % 4) / 10).toFixed(1),
    exp: 6 + (seed % 14),
    distanceKm: +(0.8 + (seed % 6) * 0.35).toFixed(1),
    etaMin: 5 + (seed % 8),
    notifyAt: 0,
    acceptAt: 999999,
    area: "Saved doctor",
    specialty: spec?.name || spec?.id || null,
    notified: true,
    stageTarget: slot,
  };
}

function requestStageCandidates(req) {
  if (!req) return [];
  if (req.stage === "my_doctor") return req.myDoctorCandidate ? [req.myDoctorCandidate] : [];
  if (req.stage === "preferred") return req.preferredCandidate ? [req.preferredCandidate] : [];
  return req.candidates || [];
}

// Live scan / lab / pharmacy / ambulance builders. Each returns real enrolled
// accounts that are online right now. Falls back to the seeded list only if no
// real account of that category is currently live, so the flow never renders empty.
// `filters` = { service?: string, specialization?: string, radiusKm?: number }
// - service / specialization match against the provider's `specialty` field
//   (comma-separated list of capabilities). Providers without any capabilities
//   listed are treated as unknown and kept in the list.
// - radiusKm filters by distance so we only ping centres that can actually reach.
function parseKm(str) {
  const m = typeof str === "string" ? str.match(/([\d.]+)\s*km/i) : null;
  return m ? parseFloat(m[1]) : null;
}
function providerHandles(providerSpecialty, term) {
  if (!term) return true;
  if (!providerSpecialty) return true; // unknown capability → don't exclude
  const caps = String(providerSpecialty).toLowerCase().split(/[,;/|]+/).map(s => s.trim()).filter(Boolean);
  if (caps.length === 0) return true;
  const t = String(term).toLowerCase().trim();
  return caps.some(c => c.includes(t) || t.includes(c));
}
function buildLiveCategory(view, seededFallback, filters) {
  const f = filters || {};
  const radius = typeof f.radiusKm === "number" ? f.radiusKm : null;
  const matches = (spec) =>
    providerHandles(spec, f.service) && providerHandles(spec, f.specialization);
  let live = liveOnlineByView(view).filter(p => matches(p.specialty));
  if (radius != null) live = live.filter(p => (p.distanceKm ?? 0) <= radius);
  const liveCands = live.map((p, i) => ({
    id: p.id,
    userId: p.userId,
    name: p.name,
    area: "Nearby",
    type: view === "diagnostic" ? "partner" : view,
    avail: 1,
    distance: (p.distanceKm ?? (0.6 + i * 0.4)).toFixed(1) + " km",
    notifyAt: 200 + i * 300,
    acceptAt: 999999,
    isLive: true,
    specialty: p.specialty || null,
  }));
  // Fall back to seeded demo entries so patient screens never render empty
  // (e.g. before any demo provider account is signed in).
  let seed = Array.isArray(seededFallback) ? seededFallback.slice() : [];
  if (radius != null) {
    const filtered = seed.filter(s => {
      const km = parseKm(s.distance);
      return km == null ? true : km <= radius;
    });
    if (filtered.length > 0) seed = filtered;
  }
  if (liveCands.length === 0) return seed;
  // Show live accounts first, then top up with a few seeded entries so the list
  // feels populated during testing.
  return [...liveCands, ...seed.slice(0, Math.max(0, 4 - liveCands.length))];
}




function tickRequest(r) {
  if (!r) return r;
  if (r.status === "broadcasting") {
    // Freeze the loop the moment a medico has accepted (assignedId set) or the
    // request was explicitly stopped — no further rebroadcasts, no duplicate offers.
    if (r.assignedId || r.stopRebroadcast) return r;
    // Manual-escalation flow for non-emergency: my_doctor / preferred stages
    // hold — StageFlowOverlay drives escalation manually.
    // Emergency cascade: auto-escalate every 60s:
    //   my_doctor (60s) → preferred (60s) → broadcast
    // giving My Doctor 3 chances (own stage + preferred + broadcast),
    // Preferred 2 chances (preferred + broadcast), same-category medicos 1 chance.
    if (r.stage && r.stage !== "broadcast") {
      const elapsed = Math.min(STAGE_TIMEOUT_MS || 60000, (r.elapsed || 0) + 250);
      if (r.emergency && elapsed >= 60000) {
        if (r.stage === "my_doctor") {
          // Advance to preferred if a preferred candidate exists, otherwise straight to broadcast.
          if (r.preferredCandidate) {
            return { ...r, stage: "preferred", candidates: [r.preferredCandidate, ...(r.myDoctorCandidate ? [r.myDoctorCandidate] : [])], elapsed: 0, remaining: 60 };
          }
          const pool = (r._broadcastPool && r._broadcastPool.length) ? r._broadcastPool : r.candidates;
          return { ...r, stage: "broadcast", candidates: pool, elapsed: 0, remaining: 60, coverageKm: (r.coverageKm || 4) + 1 };
        }
        if (r.stage === "preferred") {
          const pool = (r._broadcastPool && r._broadcastPool.length) ? r._broadcastPool : r.candidates;
          return { ...r, stage: "broadcast", candidates: pool, elapsed: 0, remaining: 60, coverageKm: (r.coverageKm || 4) + 1 };
        }
      }
      return { ...r, elapsed, remaining: Math.max(0, (60000 - elapsed) / 1000) };
    }
    const elapsed = r.elapsed + 250, remaining = Math.max(0, (60000 - elapsed) / 1000);
    const candidates = r.candidates.map(c => ({ ...c, notified: elapsed >= c.notifyAt }));
    // Auto-rebroadcast every 60s with +1 km coverage until someone accepts.
    if (elapsed >= 60000) {
      return { ...r, candidates, elapsed: 0, remaining: 60, coverageKm: (r.coverageKm || 4) + 1 };
    }
    return { ...r, candidates, elapsed, remaining };
  }

  if (r.status === "converging") {
    const doctorEtaHub = Math.max(0, r.doctorEtaHub - 7), patientEtaHub = Math.max(0, (r.patientEtaHub || 0) - 5);
    if (doctorEtaHub <= 0 && patientEtaHub <= 0) return { ...r, doctorEtaHub: 0, patientEtaHub: 0, status: "at_hub" };
    return { ...r, doctorEtaHub, patientEtaHub };
  }
  return r;
}
