const Stars = ({ v, size = 12 }) => (<span className="inline-flex items-center gap-1" style={{ color: C.gold, fontWeight: 700, fontSize: size + 1 }}><Star size={size} fill={C.gold} stroke="none" />{v}</span>);
const Avatar = ({ name, size = 44, emergency, hub }) => { const initials = name.replace("Dr. ", "").replace("Tech. ", "").split(" ").map(w => w[0]).join(""), bg = hub ? gradHub : emergency ? gradE : grad; return (<div className="flex items-center justify-center rounded-full text-white font-bold flex-shrink-0" style={{ width: size, height: size, fontSize: size * 0.34, background: bg }}>{initials}</div>); };
function CountdownRing({ remaining, total, size = 132, children }) { const r = size / 2 - 9, circ = 2 * Math.PI * r, pct = Math.max(0, remaining / total), col = pct > 0.55 ? C.primary : pct > 0.28 ? C.gold : C.emerg; return (<div className="relative" style={{ width: size, height: size }}><svg width={size} height={size} className="-rotate-90"><circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={C.line} strokeWidth="9" /><circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={col} strokeWidth="9" strokeLinecap="round" strokeDasharray={circ} strokeDashoffset={circ * (1 - pct)} style={{ transition: "stroke-dashoffset .25s linear,stroke .4s" }} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center">{children}</div></div>); }
const PrimaryBtn = ({ children, onClick, emergency, disabled, sub, hub }) => (<button onClick={onClick} disabled={disabled} className="w-full rounded-2xl text-white font-bold flex items-center justify-center gap-2 active:scale-95 transition-transform" style={{ background: disabled ? "#B9C9C3" : hub ? gradHub : emergency ? gradE : grad, padding: sub ? "11px 16px" : "15px 16px", fontSize: 15.5, boxShadow: disabled ? "none" : `0 8px 22px -8px ${hub ? C.hub : emergency ? C.emerg : C.primary}aa` }}>{children}</button>);
const Mode = ({ active, onClick, title, desc, Icon, color, soft }) => (<button onClick={onClick} className="rounded-2xl p-3 text-left transition-all active:scale-95" style={{ background: active ? soft : C.surface, border: `1.5px solid ${active ? color : C.line}` }}><Icon size={18} style={{ color: active ? color : C.sub }} /><p className="font-bold mt-1" style={{ color: C.ink, fontSize: 13.5 }}>{title}</p><p style={{ color: active ? color : C.faint, fontSize: 11 }}>{desc}</p></button>);
const Stat = ({ label, value, color }) => (<div className="rounded-xl py-2 text-center" style={{ background: C.canvas }}><p className="font-extrabold" style={{ color: color || C.ink, fontSize: 14 }}>{value}</p><p className="uppercase tracking-wide" style={{ color: C.faint, fontSize: 10 }}>{label}</p></div>);
const IconBtn = ({ Icon, label, onClick }) => (<button onClick={onClick} className="rounded-2xl flex flex-col items-center justify-center px-3 py-2" style={{ background: C.canvas, color: C.sub, cursor: "pointer", border: "none" }}><Icon size={16} /><span style={{ fontSize: 9 }}>{label}</span></button>);
const Row = ({ k, v, bold, emergency, hub }) => (<div className="flex justify-between py-1" style={{ fontSize: 13 }}><span style={{ color: C.sub }}>{k}</span><span style={{ color: emergency ? C.emerg : hub ? C.hub : C.ink, fontWeight: bold ? 800 : 600 }}>{v}</span></div>);
const Empty = ({ Icon, title, desc, hub }) => { const animated = Icon === Radio; const color = hub ? C.hub : C.faint; return (<div className="flex flex-col items-center text-center py-10 px-4"><div className="relative w-16 h-16 flex items-center justify-center mb-3">{animated && (<><span className="absolute inset-0 rounded-full animate-ping" style={{ background: color, opacity: .25, animationDuration: '2s' }} /><span className="absolute inset-2 rounded-full animate-ping" style={{ background: color, opacity: .35, animationDuration: '2s', animationDelay: '.4s' }} /></>)}<div className="relative w-14 h-14 rounded-full flex items-center justify-center" style={{ background: C.canvas }}><Icon size={26} style={{ color }} className={animated ? 'animate-pulse' : ''} /></div></div><p className="font-bold" style={{ color: C.ink, fontSize: 15 }}>{title}</p><p className="text-sm mt-1" style={{ color: C.sub, maxWidth: 250 }}>{desc}</p></div>); };
const ProgressBar = ({ progress, color }) => (<div className="rounded-full overflow-hidden" style={{ height: 6, background: C.line }}><div className="h-full rounded-full" style={{ width: `${Math.min(1, progress) * 100}%`, background: color, transition: "width .5s linear" }} /></div>);
const HubBadge = ({ type }) => { const isC = type === "clinic"; return (<span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 font-bold" style={{ background: isC ? C.clinicSoft : C.primarySoft, color: isC ? C.clinic : C.primaryDeep, fontSize: 10 }}>{isC ? <BadgeCheck size={10} /> : <Building2 size={10} />}{isC ? "Partner Clinic" : "MyDox Hub"}</span>); };

