/* ── Therapy session-package upsell (shown after a therapist session) ──
   7 / 15 / 30-session bundles with 0 / 5 / 10% discounts. Actual session
   times are NOT locked here — they're arranged by mutual agreement between
   patient and therapist. The patient can share availability preferences. */
const THERAPY_PACKAGES = [
  { id: "p7", sessions: 7, discount: 0, tag: "Starter" },
  { id: "p15", sessions: 15, discount: 0.05, tag: "Most popular" },
  { id: "p30", sessions: 30, discount: 0.10, tag: "Best value" },
];
const TP_DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const TP_SLOTS = ["Morning", "Afternoon", "Evening"];
/* friendlier therapy nouns for the package heading (keyed by therapist id) */
const THERAPY_NOUN = { physio: "physiotherapy", speech: "speech therapy", psycho: "psychotherapy", occup: "occupational therapy", resp: "respiratory therapy" };

function TherapyPackageCard({ perSession, therapistName, therapyName, accent = "#0C9668", onBook }) {
  const [pkgId, setPkgId] = useState(null);
  const [days, setDays] = useState([]);
  const [slot, setSlot] = useState(null);
  const [booked, setBooked] = useState(false);
  const pkg = THERAPY_PACKAGES.find(p => p.id === pkgId);
  const toggleDay = (d) => setDays(a => a.includes(d) ? a.filter(x => x !== d) : [...a, d]);
  const calc = (p) => { const sub = perSession * p.sessions; const save = Math.round(sub * p.discount); return { sub, save, total: sub - save, per: Math.round((sub - save) / p.sessions) }; };
  const firstName = (therapistName || "Your therapist").split(" ").slice(0, 2).join(" ");

  if (booked && pkg) {
    const c = calc(pkg); return (
      <div style={{ width: "100%", borderRadius: 18, padding: "16px", background: "#ECFDF5", border: "1.5px solid #A7F3D0", textAlign: "left", marginBottom: 12 }}>
        <p style={{ margin: 0, fontWeight: 900, color: "#065F46", fontSize: 15, display: "flex", alignItems: "center", gap: 7 }}><CircleCheck size={18} /> {pkg.sessions}-session package booked</p>
        <p style={{ margin: "7px 0 0", fontSize: 12, color: "#047857", lineHeight: 1.5 }}>{firstName} will reach out to mutually agree on your session days &amp; times.{days.length ? ` You noted you're usually free: ${days.join(", ")}${slot ? ` · ${slot.toLowerCase()}` : ""}.` : ""}</p>
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10, paddingTop: 10, borderTop: "1px solid #A7F3D0" }}>
          <span style={{ fontSize: 12, fontWeight: 800, color: "#065F46" }}>Paid · {inr(c.total)}{c.save > 0 ? `  ·  saved ${inr(c.save)}` : ""}</span>
          <span style={{ fontSize: 11, fontWeight: 700, color: "#047857" }}>{inr(c.per)}/session</span>
        </div>
      </div>
    );
  }

  return (
    <div style={{ width: "100%", borderRadius: 18, padding: "15px", background: "#fff", border: `1.5px solid ${accent}33`, textAlign: "left", marginBottom: 12, boxShadow: "0 2px 10px rgba(0,0,0,.04)" }}>
      <p style={{ margin: 0, fontWeight: 900, color: C.ink, fontSize: 14.5 }}>Continue your {therapyName || "therapy"} — book a package</p>
      <p style={{ margin: "3px 0 11px", fontSize: 11.5, color: C.sub, lineHeight: 1.45 }}>Most plans need several sessions. Bundle &amp; save, and keep the same therapist throughout.</p>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {THERAPY_PACKAGES.map(p => {
          const c = calc(p); const sel = pkgId === p.id; return (
            <button key={p.id} onClick={() => setPkgId(sel ? null : p.id)} style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 10px", borderRadius: 14, border: `1.5px solid ${sel ? accent : C.line}`, background: sel ? accent + "0D" : "#fff", cursor: "pointer", textAlign: "left", fontFamily: "'Plus Jakarta Sans',sans-serif", width: "100%" }}>
              <div style={{ width: 20, height: 20, borderRadius: "50%", border: `2px solid ${sel ? accent : C.line}`, background: sel ? accent : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{sel && <Check size={12} color="#fff" strokeWidth={3} />}</div>
              <div style={{ flex: 1, minWidth: 0, paddingRight: 4 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <span style={{ fontWeight: 800, color: C.ink, fontSize: 13.5, whiteSpace: "nowrap" }}>{p.sessions} sessions</span>
                  {p.discount > 0 && <span style={{ background: accent, color: "#fff", borderRadius: 99, padding: "1px 5px", fontSize: 9, fontWeight: 800, whiteSpace: "nowrap" }}>{Math.round(p.discount * 100)}% OFF</span>}
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 3, flexWrap: "wrap" }}>
                  <span style={{ fontSize: 10, color: C.faint, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: "100%" }}>{p.tag}</span>
                  <span style={{ fontSize: 10, color: C.line }}>•</span>
                  <span style={{ fontSize: 10.5, color: C.sub, whiteSpace: "nowrap" }}>{inr(c.per)}/sesh</span>
                </div>
              </div>
              <div style={{ textAlign: "right", flexShrink: 0, marginLeft: "auto" }}>
                <p style={{ margin: 0, fontWeight: 900, color: C.ink, fontSize: 14, whiteSpace: "nowrap" }}>{inr(c.total)}</p>
                {c.save > 0 && <p style={{ margin: 0, fontSize: 9.5, fontWeight: 700, color: accent, whiteSpace: "nowrap" }}>save {inr(c.save)}</p>}
              </div>
            </button>
          );
        })}
      </div>

      {pkg && (<>
        <div style={{ marginTop: 13, padding: "11px 12px", borderRadius: 13, background: C.canvas, border: `1px solid ${C.line}` }}>
          <p style={{ margin: "0 0 6px", fontSize: 11.5, fontWeight: 800, color: C.ink }}>📅 Timings — by mutual agreement</p>
          <p style={{ margin: "0 0 9px", fontSize: 10.5, color: C.sub, lineHeight: 1.45 }}>No fixed slots are locked now. Share when you're usually free and {firstName} will confirm each session's time directly with you.</p>
          <p style={{ margin: "0 0 5px", fontSize: 10, fontWeight: 700, color: C.faint, letterSpacing: .4 }}>USUALLY FREE ON</p>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 9 }}>
            {TP_DAYS.map(d => { const on = days.includes(d); return (<button key={d} onClick={() => toggleDay(d)} style={{ borderRadius: 99, padding: "5px 11px", border: `1.5px solid ${on ? accent : C.line}`, background: on ? accent : "#fff", color: on ? "#fff" : C.sub, fontWeight: 700, fontSize: 11, cursor: "pointer", fontFamily: "'Plus Jakarta Sans',sans-serif" }}>{d}</button>); })}
          </div>
          <p style={{ margin: "0 0 5px", fontSize: 10, fontWeight: 700, color: C.faint, letterSpacing: .4 }}>PREFERRED TIME</p>
          <div style={{ display: "flex", gap: 5 }}>
            {TP_SLOTS.map(s => { const on = slot === s; return (<button key={s} onClick={() => setSlot(on ? null : s)} style={{ flex: 1, borderRadius: 10, padding: "7px 4px", border: `1.5px solid ${on ? accent : C.line}`, background: on ? accent + "12" : "#fff", color: on ? accent : C.sub, fontWeight: 700, fontSize: 11, cursor: "pointer", fontFamily: "'Plus Jakarta Sans',sans-serif" }}>{s}</button>); })}
          </div>
        </div>
        <button onClick={() => { setBooked(true); onBook && onBook({ sessions: pkg.sessions, ...calc(pkg), days, slot }); }}
          style={{ width: "100%", marginTop: 11, borderRadius: 14, padding: "13px", border: "none", background: accent, color: "#fff", fontWeight: 800, fontSize: 14, cursor: "pointer", fontFamily: "'Plus Jakarta Sans',sans-serif", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
          Book {pkg.sessions}-session package · {inr(calc(pkg).total)}
        </button>
        <p style={{ margin: "7px 0 0", textAlign: "center", fontSize: 9.5, color: C.faint, lineHeight: 1.4 }}>Flexible — reschedule any session with {firstName}. Demo: no real payment is taken.</p>
      </>)}
    </div>
  );
}

/* ── Test category row (expandable) ─────────────────────────────── */
function TestCatRow({ cat, selectedTest, onSelectTest, emergency }) {
  const [open, setOpen] = useState(false);
  const ac = emergency ? C.emerg : C.primary, hasSelected = selectedTest && cat.tests.includes(selectedTest);
  return (
    <div style={{ borderBottom: `1px solid ${C.line}` }}>
      <button onClick={() => setOpen(o => !o)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 9, padding: "9px 13px", background: hasSelected ? `${ac}10` : "transparent", border: "none", cursor: "pointer", textAlign: "left" }}>
        <div style={{ width: 28, height: 28, borderRadius: 8, flexShrink: 0, background: `${cat.color}18`, display: "flex", alignItems: "center", justifyContent: "center" }}><cat.Icon size={13} style={{ color: cat.color }} /></div>
        <div style={{ flex: 1 }}>
          <span style={{ fontWeight: 700, color: hasSelected ? ac : C.ink, fontSize: 12.5 }}>{cat.label}</span>
          {hasSelected && <span style={{ fontSize: 9.5, color: ac, marginLeft: 5, fontWeight: 600 }}>✓ selected</span>}
          <p style={{ color: C.faint, fontSize: 10, margin: "1px 0 0" }}>{cat.tests.length} tests · starts {inr(cat.base)}</p>
        </div>
        {open ? <ChevronUp size={14} style={{ color: C.faint, flexShrink: 0 }} /> : <ChevronDown size={14} style={{ color: C.faint, flexShrink: 0 }} />}
      </button>
      {open && (
        <div style={{ padding: "0 13px 9px 50px", display: "flex", flexDirection: "column", gap: 1 }}>
          {cat.tests.map(t => {
            const isSel = selectedTest === t;
            return (
              <button key={t} onClick={() => onSelectTest(isSel ? null : t)} style={{ textAlign: "left", padding: "6px 9px", borderRadius: 8, border: "none", cursor: "pointer", background: isSel ? (emergency ? C.emergSoft : C.primarySoft) : "transparent", display: "flex", alignItems: "center", gap: 6, transition: "background .12s" }}>
                <span style={{ width: 5, height: 5, borderRadius: "50%", flexShrink: 0, background: isSel ? ac : C.line }} />
                <span style={{ fontSize: 12, fontWeight: isSel ? 700 : 500, color: isSel ? ac : C.ink }}>{t}</span>
                {isSel && <Check size={11} style={{ color: ac, marginLeft: "auto" }} />}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ── Radar ─────────────────────────────────────────────────────── */
function Radar({ candidates, assignedId, hub }) {
  const ac = hub ? C.hub : C.primary, pts = candidates.map((c, i) => { const ang = (i / candidates.length) * Math.PI * 2 - Math.PI / 2, rad = 30 + (i % 3) * 18; return { ...c, x: 50 + Math.cos(ang) * rad, y: 50 + Math.sin(ang) * rad }; });
  return (
    <div className="relative mx-auto" style={{ width: 210, height: 210 }}>
      {[1, 0.66, 0.33].map((s, i) => (<div key={i} className="absolute rounded-full" style={{ inset: `${(1 - s) * 105}px`, border: `1px solid ${C.line}` }} />))}
      <div className="absolute rounded-full overflow-hidden" style={{ inset: 0 }}><div className="absolute inset-0" style={{ background: `conic-gradient(from 0deg,${ac}00 0deg,${ac}33 50deg,${ac}00 60deg)`, animation: "radar 2.6s linear infinite" }} /></div>
      <div className="absolute flex items-center justify-center rounded-full text-white" style={{ left: "50%", top: "50%", width: 34, height: 34, transform: "translate(-50%,-50%)", background: hub ? C.hub : C.ink }}>{hub ? <Building2 size={16} /> : <Hospital size={16} />}</div>
      {pts.map(p => { const accepted = assignedId && p.id === assignedId, lit = p.notified; return (<div key={p.id} className="absolute" style={{ left: `${p.x}%`, top: `${p.y}%`, transform: "translate(-50%,-50%)" }}>{lit && !assignedId && <span className="absolute rounded-full" style={{ inset: -6, border: `2px solid ${ac}`, animation: "ping 1.4s ease-out infinite" }} />}<div className="flex items-center justify-center rounded-full text-white" style={{ width: 26, height: 26, background: accepted ? ac : lit ? C.primaryDeep : "#C4D3CD", transform: accepted ? "scale(1.3)" : lit ? "scale(1)" : "scale(.8)", transition: "all .35s", boxShadow: accepted ? `0 0 0 4px ${ac}33` : "none" }}>{accepted ? <Check size={14} /> : <Stethoscope size={12} />}</div></div>); })}
    </div>
  );
}

/* ── Hub Discovery Mini-map ─────────────────────────────────────── */
function MiniHubMap({ filteredIds }) {
  const positions = { h1: { x: 88, y: 88 }, h2: { x: 152, y: 58 }, h3: { x: 198, y: 108 }, h4: { x: 243, y: 44 } };
  return (
    <div className="relative w-full rounded-2xl overflow-hidden" style={{ height: 148, background: "#DCE8E2" }}>
      <div style={{ position: "absolute", inset: 0, backgroundImage: `linear-gradient(${C.line} 1px,transparent 1px),linear-gradient(90deg,${C.line} 1px,transparent 1px)`, backgroundSize: "24px 24px", opacity: 0.5 }} />
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} viewBox="0 0 280 148">
        <circle cx="32" cy="100" r="8" fill={C.ink} /><circle cx="32" cy="100" r="14" fill="none" stroke={C.ink} strokeWidth="1.5" opacity="0.3" />
        <text x="32" y="116" textAnchor="middle" fontSize="9" fill={C.sub}>You</text>
        {HUBS.map(hub => { const pos = positions[hub.id]; if (!pos) return null; const isA = filteredIds.includes(hub.id), col = hub.type === "clinic" ? C.clinic : C.primary; return (<g key={hub.id}>{isA && <line x1="32" y1="100" x2={pos.x} y2={pos.y} stroke={col} strokeWidth="1" strokeDasharray="4 3" opacity="0.6" />}<circle cx={pos.x} cy={pos.y} r={isA ? 11 : 7} fill={isA ? col : "#B9C9C3"} style={{ transition: "all .3s" }} />{isA && <circle cx={pos.x} cy={pos.y} r="17" fill="none" stroke={col} strokeWidth="1.5" opacity="0.35" style={{ animation: "ping 2s ease-out infinite" }} />}<text x={pos.x} y={pos.y + 4} textAnchor="middle" fontSize="9" fill="white" fontWeight="bold">{hub.type === "clinic" ? "C" : "M"}</text><text x={pos.x} y={pos.y + 20} textAnchor="middle" fontSize="8" fill={isA ? col : C.faint}>{hub.distance}km</text></g>); })}
      </svg>
    </div>
  );
}

/* ── Hub Card (discovery screen) ───────────────────────────────── */
function HubCard({ hub, emergency, onBook }) {
  const isC = hub.type === "clinic";
  return (
    <div className="rounded-2xl p-4 mb-3" style={{ background: C.surface, border: `1.5px solid ${isC ? C.clinicSoft : C.primarySoft}` }}>
      <div className="flex items-start justify-between mb-2">
        <div style={{ flex: 1, paddingRight: 12 }}><HubBadge type={hub.type} /><p className="font-extrabold mt-1.5" style={{ color: C.ink, fontSize: 15 }}>{hub.name}</p><p className="flex items-center gap-1 mt-0.5" style={{ color: C.sub, fontSize: 12 }}><MapPin size={11} />{hub.address}</p></div>
        <div className="text-right flex-shrink-0"><Stars v={hub.rating} /><p className="mt-0.5 font-extrabold" style={{ color: C.primary, fontSize: 14 }}>{hub.distance} km</p></div>
      </div>
      <div className="flex flex-wrap gap-1.5 mb-3">{hub.amenities.slice(0, 4).map(a => (<span key={a} className="rounded-lg px-2 py-0.5 font-semibold" style={{ background: C.canvas, color: C.sub, fontSize: 10 }}>{a}</span>))}</div>
      <div className="grid grid-cols-3 gap-2 mb-3">
        <Stat label="Doctors" value={hub.docs} /><Stat label="Rooms" value={`${hub.occupied}/${hub.rooms}`} />
        <div className="rounded-xl py-2 text-center" style={{ background: isC ? C.clinicSoft : C.primarySoft }}><p className="font-extrabold" style={{ color: isC ? C.clinic : C.primary, fontSize: 14 }}>{hub.patEtaMin} min</p><p className="uppercase tracking-wide" style={{ color: isC ? C.clinic : C.primaryDeep, fontSize: 10 }}>Your ETA</p></div>
      </div>
      <PrimaryBtn onClick={() => onBook(hub)} emergency={emergency}><Navigation size={16} /> Book at this hub</PrimaryBtn>
    </div>
  );
}

/* ── Convergence map ────────────────────────────────────────────── */
function MapConverge({ req }) {
  const docPct = req.doctorInitEta > 0 ? Math.min(1, 1 - req.doctorEtaHub / req.doctorInitEta) : 1;
  const patPct = req.patInitEta > 0 ? Math.min(1, 1 - req.patientEtaHub / req.patInitEta) : 1;
  const docLeft = 90 - docPct * 40, docTop = 25 + docPct * 27, patLeft = 10 + patPct * 40, patTop = 80 - patPct * 28;
  const atHub = req.status === "at_hub", doc = req.candidates?.find(c => c.id === req.assignedId);
  return (
    <div className="w-full rounded-2xl overflow-hidden relative" style={{ height: 192, background: "#DCE8E2" }}>
      <div style={{ position: "absolute", inset: 0, backgroundImage: `linear-gradient(${C.line} 1px,transparent 1px),linear-gradient(90deg,${C.line} 1px,transparent 1px)`, backgroundSize: "24px 24px", opacity: 0.5 }} />
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} viewBox="0 0 100 100" preserveAspectRatio="none">
        <path d="M90,25 Q70,40 50,52" fill="none" stroke={C.primary} strokeWidth="0.5" strokeDasharray="3 2" opacity="0.7" vectorEffect="non-scaling-stroke" />
        <path d="M10,80 Q30,66 50,52" fill="none" stroke="#6366F1" strokeWidth="0.5" strokeDasharray="3 2" opacity="0.7" vectorEffect="non-scaling-stroke" />
        <circle cx="50" cy="52" r={atHub ? "6" : "5"} fill="white" stroke={atHub ? C.primary : C.emerg} strokeWidth="0.6" />
        <text x="50" y="54.8" textAnchor="middle" fontSize="6" fill={atHub ? C.primary : C.emerg} fontWeight="bold">+</text>
      </svg>
      {atHub && <div style={{ position: "absolute", left: "50%", top: "52%", transform: "translate(-50%,-50%)", width: 44, height: 44, borderRadius: "50%", border: `2.5px solid ${C.primary}`, animation: "ping 1.8s ease-out infinite" }} />}
      <div style={{ position: "absolute", left: `${docLeft}%`, top: `${docTop}%`, transform: "translate(-50%,-50%)", transition: "left .5s linear,top .5s linear", width: 28, height: 28, borderRadius: "50%", background: C.primary, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 2px 8px ${C.primary}66` }}><Stethoscope size={14} color="white" /></div>
      <div style={{ position: "absolute", left: `${patLeft}%`, top: `${patTop}%`, transform: "translate(-50%,-50%)", transition: "left .5s linear,top .5s linear", width: 28, height: 28, borderRadius: "50%", background: "#6366F1", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 2px 8px rgba(99,102,241,.55)" }}><User size={14} color="white" /></div>
      <div style={{ position: "absolute", top: 8, left: 8, display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10, fontWeight: 700, color: C.primaryDeep, background: C.primarySoft, borderRadius: 7, padding: "3px 7px" }}><Stethoscope size={9} />{doc?.name.split(" ").pop() || "Dr."} · {atHub ? "At hub" : Math.max(0, Math.ceil(req.doctorEtaHub / 60)) + " min"}</span>
        <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10, fontWeight: 700, color: "#4338CA", background: "#EEF2FF", borderRadius: 7, padding: "3px 7px" }}><User size={9} />You · {atHub ? "At hub" : Math.max(0, Math.ceil(req.patientEtaHub / 60)) + " min"}</span>
      </div>
      <div style={{ position: "absolute", bottom: 8, left: 8, right: 8, background: "rgba(255,255,255,.93)", borderRadius: 12, padding: "6px 12px", display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ color: C.emerg, fontSize: 18, fontWeight: 800, lineHeight: 1 }}>+</span>
        <div style={{ flex: 1 }}><p style={{ color: C.ink, fontWeight: 700, fontSize: 12.5 }}>{req.hub?.name || "Scan Centre"}</p><p style={{ color: C.sub, fontSize: 11 }}>{req.hub?.address || "Nearby"}</p></div>
        <button onClick={() => toast("Centering map on your area")} style={{ background: C.primarySoft, color: C.primaryDeep, borderRadius: 9, padding: "5px 10px", fontSize: 11, fontWeight: 700, display: "flex", alignItems: "center", gap: 3, flexShrink: 0, border: "none", cursor: "pointer" }}><Navigation size={11} /> Go</button>
      </div>
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════
   HUB PORTAL + MEDICO APP + ADMIN (unchanged from V3)
══════════════════════════════════════════════════════════════ */
function RoomCard({ room, onDispatch }) {
  const sc = {
    vacant: { color: C.primary, soft: C.primarySoft, label: "Available" },
    occupied: { color: C.gold, soft: C.clinicSoft, label: "In Session" },
    dispatching: { color: C.primary, soft: "#E8F5E9", label: "Dr. En Route" },
    cleaning: { color: C.faint, soft: C.canvas, label: "Preparing" },
  }[room.status] || { color: C.faint, soft: C.canvas, label: "—" };
  return (
    <div className="rounded-2xl p-3" style={{ background: sc.soft, border: `1.5px solid ${sc.color}30` }}>
      <div className="flex items-center justify-between mb-2">
        <span className="font-extrabold" style={{ color: C.ink, fontSize: 12 }}>{room.num}</span>
        <span className="flex items-center gap-1.5 rounded-full px-2 py-0.5 font-bold"
          style={{ background: "rgba(255,255,255,.65)", color: sc.color, fontSize: 10 }}>
          <span className="w-1.5 h-1.5 rounded-full"
            style={{ background: sc.color, animation: room.status === "dispatching" ? "pulse 1.2s infinite" : "none" }} />
          {sc.label}
        </span>
      </div>
      {(room.status === "occupied" || room.status === "dispatching") && (
        <>
          <p className="font-bold truncate" style={{ color: C.ink, fontSize: 12 }}>{room.patient}</p>
          <p style={{ color: C.sub, fontSize: 11 }}>{room.spec}</p>
          <p style={{ color: sc.color, fontSize: 11, fontWeight: 700, marginTop: 2 }}>
            {room.status === "occupied"
              ? `${room.doctor} · ${room.mins} min`
              : `${room.doctor} · ETA ${room.etaMin} min`}
          </p>
        </>
      )}
      {room.status === "vacant" && (
        <button onClick={() => onDispatch && onDispatch(room, "doctor")}
          className="w-full mt-1 rounded-xl py-1.5 flex items-center justify-center gap-1 font-bold"
          style={{ background: "rgba(255,255,255,.75)", color: C.primary, fontSize: 11 }}>
          <Plus size={12} /> Book Appointment
        </button>
      )}
      {room.status === "cleaning" && (
        <p style={{ color: C.faint, fontSize: 11 }}>Ready in ~10 min</p>
      )}
    </div>
  );
}

/* Doctor En Route (hub-initiated tracking) */
function HubDoctorEnRoute({ hubReq, onStart }) {
  const doc = hubReq.candidates?.find(c => c.id === hubReq.assignedId);
  const pct = hubReq.doctorInitEta > 0 ? Math.min(1, 1 - hubReq.doctorEtaHub / hubReq.doctorInitEta) : 1;
  const arrived = hubReq.status === "at_hub";
  return (
    <div className="rounded-2xl overflow-hidden" style={{ border: `1.5px solid ${C.hub}33` }}>
      <div className="px-4 pt-3 pb-2" style={{ background: C.hubSoft }}>
        <div className="flex items-center gap-2 mb-1">
          <span className="w-2 h-2 rounded-full" style={{ background: C.hub, animation: "pulse 1.4s infinite" }} />
          <span className="font-bold" style={{ color: C.hub, fontSize: 12 }}>
            {arrived ? hubReq?.spec?.type === "scan" ? "Scan centre ready" : "Doctor arrived at hub" : hubReq?.spec?.type === "scan" ? "Scan centre en route" : "Doctor en route to hub"}
          </span>
        </div>
        <p className="font-extrabold" style={{ color: C.ink, fontSize: 15 }}>{doc?.name}</p>
        <p style={{ color: C.sub, fontSize: 12 }}>{hubReq.spec.name} · Room {hubReq.roomLabel}</p>
      </div>
      <div className="px-4 py-3" style={{ background: C.surface }}>
        <div className="flex justify-between mb-1.5">
          <span style={{ color: C.sub, fontSize: 12 }}>ETA to hub</span>
          <span className="font-extrabold" style={{ color: arrived ? C.primary : C.hub, fontSize: 13 }}>
            {arrived ? "Here ✓" : Math.max(0, Math.ceil(hubReq.doctorEtaHub / 60)) + " min"}
          </span>
        </div>
        <ProgressBar progress={pct} color={C.hub} />
        <div className="grid grid-cols-3 gap-2 mt-3">
          <Stat label="Room" value={hubReq.roomLabel} color={C.hub} />
          <Stat label="OTP" value={hubReq.otp} />
          <Stat label="Fee" value={inr(hubReq.fare.total)} color={C.hub} />
        </div>
        {arrived && (
          <div className="mt-3">
            <PrimaryBtn sub hub onClick={() => onStart && onStart()}>
              <CircleCheck size={15} /> Start session
            </PrimaryBtn>
          </div>
        )}
      </div>
    </div>
  );
}

/* Queue Row */
function QueueRow({ item, isLive }) {
  const statusMap = {
    in_session: ["In Session", C.gold], broadcasting: ["Finding Dr.", C.hub],
    en_route: ["En Route", C.primary], converging: ["Converging", C.primary],
    at_hub: ["At Hub", C.primary], completed: ["Done", C.faint],
  };
  const [lbl, col] = statusMap[item.status] || ["—", C.faint];
  return (
    <div className="flex items-center gap-3 py-2.5" style={{ borderTop: `1px solid ${C.line}` }}>
      <div className="text-center flex-shrink-0" style={{ width: 38 }}>
        <p className="font-bold" style={{ color: C.ink, fontSize: 12 }}>{item.time}</p>
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-bold truncate" style={{ color: C.ink, fontSize: 13 }}>{item.patient}</p>
        <p style={{ color: C.sub, fontSize: 11.5 }}>{item.spec} · {item.room}</p>
        <p style={{ color: C.faint, fontSize: 11 }}>{item.doctor}</p>
      </div>
      <div className="text-right flex-shrink-0">
        <span className="rounded-full px-2 py-0.5 font-bold" style={{ background: col + "22", color: col, fontSize: 10 }}>
          {isLive && <span style={{ display: "inline-block", width: 6, height: 6, borderRadius: "50%", background: col, marginRight: 3, animation: "pulse 1.2s infinite" }} />}
          {lbl}
        </span>
        <p className="mt-0.5 font-extrabold" style={{ color: C.ink, fontSize: 12 }}>{item.fee}</p>
      </div>
    </div>
  );
}

