/* ── Collaboration Map — two-way referral relationships between colleagues ──
   A COORDINATION & INSIGHT tool, not a points scheme. It shows whether you and a
   colleague exchange patients roughly evenly (a healthy two-way relationship) or
   one-directionally. Referrals carry no payment and earn no volume-based CCP —
   only the flat documentation credit for completing a case summary. The "balance"
   is information about a relationship; it never nets into money or rewards. */
const COLLEAGUE_REFERRALS = [
  { id: "c1", name: "Dr. Anjali Mehta", spec: "Gynecologist", place: "Ruby Hall · Koregaon Park", sent: 6, received: 5, last: "Antenatal high-risk", lastDate: "2 days ago" },
  { id: "c2", name: "Dr. Sanjay Rao", spec: "Neurologist", place: "Poona Hospital · Magarpatta", sent: 4, received: 4, last: "Seizure work-up", lastDate: "4 days ago" },
  { id: "c3", name: "Dr. Imran Sheikh", spec: "Orthopedic Surgeon", place: "Holy Family · Koregaon Park", sent: 8, received: 2, last: "Fracture fixation", lastDate: "Yesterday" },
  { id: "c4", name: "Dr. Kavya Nair", spec: "Dermatologist", place: "Skin & You · Bavdhan", sent: 1, received: 5, last: "Psoriasis flare", lastDate: "1 week ago" },
  { id: "c5", name: "Dr. Vikram Iyer", spec: "Cardiologist", place: "Jehangir Hospital · Yerwada", sent: 3, received: 3, last: "Chest pain · TMT", lastDate: "3 days ago" },
  { id: "c6", name: "Dr. Sneha Patil", spec: "Pediatrician", place: "Jupiter Hospital · Baner", sent: 5, received: 6, last: "Neonatal jaundice", lastDate: "5 days ago" },
  { id: "c7", name: "Dr. Arjun Mehta", spec: "Gastroenterologist", place: "Hinduja · Karve Nagar", sent: 2, received: 0, last: "Endoscopy referral", lastDate: "2 weeks ago" },
];
const collabNet = (s, r) => s - r;                  // + you sent more, − they sent more
const collabBalanced = (s, r) => Math.abs(s - r) <= 1;     // within 1 either way = healthy two-way

function CollaborationMapOverlay({ onClose, onMessage }) {
  const A = "#4F46E5", D = "#7C3AED", SENT = "#6366F1", RECV = "#0EA5A4";
  const [rows, setRows] = useState(COLLEAGUE_REFERRALS.map(r => ({ ...r })));
  const [filter, setFilter] = useState("all");        // all | balanced | oneway
  const [openId, setOpenId] = useState(null);
  const wrap = { position: "absolute", inset: 0, zIndex: 86, background: C.surface, display: "flex", flexDirection: "column", fontFamily: "'Plus Jakarta Sans',sans-serif" };

  const totalSent = rows.reduce((a, r) => a + r.sent, 0);
  const totalRecv = rows.reduce((a, r) => a + r.received, 0);
  const net = totalSent - totalRecv;
  const balancedCount = rows.filter(r => collabBalanced(r.sent, r.received)).length;
  const gmax = Math.max(1, ...rows.map(r => Math.max(r.sent, r.received)));
  const shown = rows.filter(r => filter === "all" ? true : filter === "balanced" ? collabBalanced(r.sent, r.received) : !collabBalanced(r.sent, r.received));
  const bump = (id, key) => setRows(rs => rs.map(r => r.id === id ? { ...r, [key]: r[key] + 1, lastDate: "Just now", last: key === "sent" ? "You referred a patient" : "They referred a patient" } : r));

  const NetChip = ({ s, r }) => {
    const n = collabNet(s, r); const bal = collabBalanced(s, r);
    const bg = bal ? "#DCFCE7" : "#FEF3C7"; const fg = bal ? "#15803D" : "#B45309";
    const label = n === 0 ? "Even" : `${n > 0 ? "You" : "Them"} +${Math.abs(n)}`;
    return <span style={{ background: bg, color: fg, borderRadius: 99, padding: "3px 9px", fontSize: 10, fontWeight: 800, whiteSpace: "nowrap" }}>{label}</span>;
  };

  return (
    <div style={wrap}>
      <div style={{ padding: "14px 16px 12px", display: "flex", alignItems: "center", gap: 12, background: `linear-gradient(135deg,${A},${D})`, flexShrink: 0 }}>
        <button onClick={onClose} style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(255,255,255,.2)", border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}><ChevronLeft size={20} color="#fff" /></button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ margin: 0, fontSize: 16, fontWeight: 800, color: "#fff" }}>Collaboration Map</p>
          <p style={{ margin: "1px 0 0", fontSize: 11, color: "rgba(255,255,255,.85)" }}>Your two-way referral relationships</p>
        </div>
        <span style={{ fontSize: 22 }}>🗺️</span>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "14px 16px 24px", scrollbarWidth: "none" }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 12 }}>
          {[["Sent", totalSent, SENT], ["Received", totalRecv, RECV], ["Colleagues", rows.length, A]].map(([l, v, col]) => (
            <div key={l} style={{ background: C.canvas, border: `1px solid ${C.line}`, borderRadius: 13, padding: "11px 8px", textAlign: "center" }}>
              <p style={{ margin: 0, fontWeight: 800, fontSize: 19, color: col, lineHeight: 1 }}>{v}</p>
              <p style={{ margin: "3px 0 0", fontSize: 10, color: C.sub, fontWeight: 600 }}>{l}</p>
            </div>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: `linear-gradient(135deg,${A}0D,${D}0D)`, border: `1px solid ${A}22`, borderRadius: 13, padding: "10px 13px", marginBottom: 12 }}>
          <TrendingUp size={16} color={A} style={{ flexShrink: 0 }} />
          <p style={{ margin: 0, fontSize: 11.5, color: C.ink, fontWeight: 600, lineHeight: 1.4, flex: 1 }}>You've referred <b>{totalSent}</b> and received <b>{totalRecv}</b> — net {net === 0 ? "even" : `${net > 0 ? "+" : ""}${net}`}. <b style={{ color: "#15803D" }}>{balancedCount}</b> of {rows.length} relationships are balanced.</p>
        </div>

        <div style={{ background: C.canvas, borderRadius: 13, padding: "11px 13px", marginBottom: 14, border: `1px solid ${C.line}`, display: "flex", gap: 9 }}>
          <ShieldCheck size={18} color={A} style={{ flexShrink: 0, marginTop: 1 }} />
          <p style={{ margin: 0, fontSize: 11, color: C.sub, fontWeight: 600, lineHeight: 1.5 }}>This is a <b>coordination tool, not a points scheme</b>. Referrals carry no payment and earn no volume-based reward — only a flat <b style={{ color: A }}>documentation credit</b> for completing a case summary. A balanced map simply reflects a healthy two-way relationship; it never converts to money or CCP.</p>
        </div>

        <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
          {[["all", "All"], ["balanced", "Balanced"], ["oneway", "One-directional"]].map(([id, lbl]) => {
            const on = filter === id; return (
              <button key={id} onClick={() => setFilter(id)} style={{ flex: 1, padding: "7px 4px", borderRadius: 10, border: `1.5px solid ${on ? A : C.line}`, background: on ? `${A}10` : "#fff", color: on ? A : C.sub, fontWeight: 700, fontSize: 10.5, cursor: "pointer", fontFamily: "inherit" }}>{lbl}</button>
            );
          })}
        </div>

        <div style={{ display: "flex", gap: 14, marginBottom: 10, padding: "0 2px" }}>
          <span style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 10, color: C.sub, fontWeight: 600 }}><span style={{ width: 9, height: 9, borderRadius: 2, background: SENT }} />You → them</span>
          <span style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 10, color: C.sub, fontWeight: 600 }}><span style={{ width: 9, height: 9, borderRadius: 2, background: RECV }} />Them → you</span>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 9 }}>
          {shown.map(r => {
            const open = openId === r.id; const sPct = r.sent / gmax * 50; const rPct = r.received / gmax * 50;
            return (
              <div key={r.id} style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 15, padding: "12px 13px", boxShadow: "0 2px 8px rgba(0,0,0,.03)" }}>
                <button onClick={() => setOpenId(open ? null : r.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 11, background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left", fontFamily: "inherit" }}>
                  <div style={{ width: 40, height: 40, borderRadius: 11, background: `${A}12`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontWeight: 800, color: A, fontSize: 14 }}>{r.name.replace("Dr. ", "").split(" ").map(w => w[0]).slice(0, 2).join("")}</div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <p style={{ margin: 0, fontWeight: 800, color: C.ink, fontSize: 13.5, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.name}</p>
                    <p style={{ margin: "1px 0 0", fontSize: 10.5, color: C.faint, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.spec} · {r.place}</p>
                  </div>
                  <NetChip s={r.sent} r={r.received} />
                  {open ? <ChevronUp size={16} color={C.faint} /> : <ChevronDown size={16} color={C.faint} />}
                </button>

                <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 11 }}>
                  <span style={{ fontSize: 11, fontWeight: 800, color: SENT, width: 18, textAlign: "right" }}>{r.sent}</span>
                  <div style={{ flex: 1, height: 9, borderRadius: 99, background: C.canvas, position: "relative", overflow: "hidden" }}>
                    <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: "50%", display: "flex", justifyContent: "flex-end" }}><div style={{ width: `${sPct * 2}%`, background: SENT }} /></div>
                    <div style={{ position: "absolute", right: 0, top: 0, bottom: 0, width: "50%", display: "flex", justifyContent: "flex-start" }}><div style={{ width: `${rPct * 2}%`, background: RECV }} /></div>
                    <div style={{ position: "absolute", left: "50%", top: -1, bottom: -1, width: 2, background: "#fff", transform: "translateX(-50%)" }} />
                  </div>
                  <span style={{ fontSize: 11, fontWeight: 800, color: RECV, width: 18 }}>{r.received}</span>
                </div>

                {open && (
                  <div style={{ marginTop: 12, paddingTop: 11, borderTop: `1px solid ${C.line}` }}>
                    <p style={{ margin: "0 0 9px", fontSize: 11, color: C.sub, lineHeight: 1.5 }}>Last exchange: <b style={{ color: C.ink }}>{r.last}</b> · {r.lastDate}. {collabBalanced(r.sent, r.received) ? "This is a healthy two-way relationship." : r.sent > r.received ? "You've sent more than you've received — reciprocity would balance this." : "They've sent you more than you've sent back."}</p>
                    <p style={{ margin: "0 0 6px", fontSize: 9.5, fontWeight: 800, color: C.faint, letterSpacing: .4 }}>LOG A REFERRAL (updates the balance live)</p>
                    <div style={{ display: "flex", gap: 7 }}>
                      <button onClick={() => bump(r.id, "sent")} style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, borderRadius: 11, padding: "10px", border: `1.5px solid ${SENT}`, background: `${SENT}0D`, color: SENT, fontWeight: 800, fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}><ArrowRight size={14} /> I referred to them</button>
                      <button onClick={() => bump(r.id, "received")} style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, borderRadius: 11, padding: "10px", border: `1.5px solid ${RECV}`, background: `${RECV}0D`, color: RECV, fontWeight: 800, fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}><ArrowRight size={14} style={{ transform: "rotate(180deg)" }} /> They referred to me</button>
                    </div>
                    <button onClick={() => onMessage && onMessage({ name: r.name, spec: r.spec, mode: "chat" })} style={{ width: "100%", marginTop: 7, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, borderRadius: 11, padding: "10px", border: `1px solid ${C.line}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 11.5, cursor: "pointer", fontFamily: "inherit" }}><MessageSquare size={14} /> Message {r.name.split(" ").slice(0, 2).join(" ")}</button>
                  </div>
                )}
              </div>
            );
          })}
          {shown.length === 0 && (<div style={{ textAlign: "center", padding: "30px 16px" }}><div style={{ fontSize: 30, marginBottom: 8 }}>🗺️</div><p style={{ margin: 0, fontWeight: 800, color: C.ink, fontSize: 13.5 }}>No relationships in this view</p><p style={{ margin: "4px 0 0", color: C.faint, fontSize: 11.5 }}>Switch the filter to see more.</p></div>)}
        </div>
      </div>
    </div>
  );
}

function ReferToHospitalOverlay({ onClose, onRefer }) {
  const C = { ink: "#1F2937", sub: "#6B7280", faint: "#9CA3AF", line: "#E5E7EB", canvas: "#F9FAFB" };
  const A = "#4F46E5", D = "#6D28D9";
  const [patient, setPatient] = React.useState("");
  const [hosp, setHosp] = React.useState(null);
  const [proc, setProc] = React.useState(null);
  const [done, setDone] = React.useState(null);
  const ccp = DOC_SUMMARY_CCP; // flat documentation credit — independent of any bill or hospital
  const ready = patient.trim() && hosp && proc;
  const wrap = { position: "absolute", inset: 0, zIndex: 86, background: "#fff", display: "flex", flexDirection: "column", fontFamily: "'Plus Jakarta Sans',sans-serif" };

  if (done) return (
    <div style={wrap}>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "30px 26px", textAlign: "center" }}>
        <div style={{ width: 78, height: 78, borderRadius: "50%", background: "#EDE9FE", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 18 }}><Check size={40} color={D} strokeWidth={3} /></div>
        <p style={{ margin: 0, fontSize: 21, fontWeight: 800, color: C.ink }}>Referral sent</p>
        <p style={{ margin: "8px 0 0", fontSize: 13.5, color: C.sub, lineHeight: 1.5, maxWidth: 300 }}>{done.patient} has been referred to {done.hospital} for {done.reason}. The hospital will receive the case summary and contact the patient.</p>
        <div style={{ marginTop: 20, width: "100%", maxWidth: 320, background: `linear-gradient(135deg,${A},${D})`, borderRadius: 16, padding: "16px", color: "#fff" }}>
          <p style={{ margin: 0, fontSize: 11, opacity: .85, fontWeight: 700 }}>Documentation reward</p>
          <div style={{ display: "flex", alignItems: "baseline", gap: 7, marginTop: 3 }}><span style={{ fontSize: 34, fontWeight: 800, lineHeight: 1, color: "#FBBF24" }}>+{done.ccp}</span><span style={{ fontSize: 14, fontWeight: 800 }}>CCP</span></div>
          <p style={{ margin: "7px 0 0", fontSize: 11, opacity: .9 }}>For completing a structured case summary — a documentation reward, not a payment for the referral.</p>
        </div>
        <button onClick={onClose} style={{ marginTop: 22, width: "100%", maxWidth: 320, padding: "14px", borderRadius: 13, border: "none", background: A, color: "#fff", fontSize: 14, fontWeight: 800, cursor: "pointer", fontFamily: "inherit" }}>Done</button>
      </div>
    </div>
  );

  return (
    <div style={wrap}>
      <div style={{ padding: "14px 16px 12px", display: "flex", alignItems: "center", gap: 12, background: `linear-gradient(135deg,${A},${D})`, flexShrink: 0 }}>
        <button onClick={onClose} style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(255,255,255,.2)", border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}><ChevronLeft size={20} color="#fff" /></button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ margin: 0, fontSize: 16, fontWeight: 800, color: "#fff" }}>Refer to partner hospital</p>
          <p style={{ margin: "1px 0 0", fontSize: 11, color: "rgba(255,255,255,.85)" }}>Onward referral for advanced care</p>
        </div>
        <span style={{ fontSize: 24 }}>🏥</span>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "14px 16px 20px", scrollbarWidth: "none" }}>
        {/* transparency note — referrals are free, only documentation is rewarded */}
        <div style={{ background: C.canvas, borderRadius: 14, padding: "12px 14px", marginBottom: 18, border: `1px solid ${C.line}`, display: "flex", gap: 10 }}>
          <span style={{ fontSize: 20 }}>🩺</span>
          <p style={{ margin: 0, fontSize: 11.5, color: C.sub, fontWeight: 600, lineHeight: 1.5 }}>Refer based only on your patient's clinical needs. Referrals are <b>free</b> and carry no payment to you or from the hospital. Completing a structured case summary earns a flat <b style={{ color: A }}>+{DOC_SUMMARY_CCP} CCP</b> for thorough documentation.</p>
        </div>

        <p style={{ margin: "0 0 7px", fontSize: 12.5, fontWeight: 800, color: C.ink }}>Patient</p>
        <input value={patient} onChange={e => setPatient(e.target.value)} placeholder="Patient name" style={{ width: "100%", boxSizing: "border-box", border: `1.5px solid ${patient.trim() ? A : C.line}`, outline: "none", background: C.canvas, borderRadius: 13, padding: "12px 13px", fontSize: 14, fontWeight: 600, color: C.ink, fontFamily: "inherit" }} />
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8, marginBottom: 18 }}>
          {["Ramesh K.", "Priya Sharma", "Imran Sheikh", "Meena Tiwari"].map(n => (
            <button key={n} onClick={() => setPatient(n)} style={{ padding: "6px 11px", borderRadius: 99, border: `1px solid ${C.line}`, background: patient === n ? `${A}12` : "#fff", color: patient === n ? A : C.sub, fontSize: 11, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{n}</button>
          ))}
        </div>

        <p style={{ margin: "0 0 8px", fontSize: 12.5, fontWeight: 800, color: C.ink }}>Partner hospital</p>
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
          {PARTNER_HOSPITALS.map(h => {
            const on = hosp?.name === h.name; return (
              <button key={h.name} onClick={() => setHosp(h)} style={{ display: "flex", alignItems: "center", gap: 11, padding: "11px 13px", borderRadius: 13, border: `1.5px solid ${on ? A : C.line}`, background: on ? `${A}0D` : "#fff", cursor: "pointer", textAlign: "left", fontFamily: "inherit" }}>
                <div style={{ width: 36, height: 36, borderRadius: 10, background: "#EEF2FF", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Building2 size={17} color={A} /></div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ margin: 0, fontSize: 13, fontWeight: 800, color: C.ink }}>{h.name}</p>
                  <p style={{ margin: "0 0 4px", fontSize: 10.5, color: C.faint }}>{h.area} · {h.tag}</p>
                  <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                    {bedBreakdown(h).filter(b => ["general", "icu"].includes(b.key)).map(b => {
                      const st = bedStatus(b.n); return (
                        <span key={b.key} style={{ background: st.bg, color: st.c, borderRadius: 6, padding: "2px 7px", fontSize: 9, fontWeight: 800 }}>{b.label}: {st.t}</span>
                      );
                    })}
                    <span style={{ color: "#0A7A54", fontSize: 8.5, fontWeight: 700, alignSelf: "center" }}>🟢 live</span>
                  </div>
                </div>
                {on ? <span style={{ width: 22, height: 22, borderRadius: "50%", background: A, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Check size={13} color="#fff" strokeWidth={3} /></span> : <span style={{ width: 20, height: 20, borderRadius: "50%", border: `2px solid ${C.line}`, flexShrink: 0 }} />}
              </button>
            );
          })}
        </div>

        <p style={{ margin: "0 0 8px", fontSize: 12.5, fontWeight: 800, color: C.ink }}>Reason / procedure</p>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {REFERRAL_PROCEDURES.map(p => {
            const on = proc?.name === p.name; return (
              <button key={p.name} onClick={() => setProc(p)} style={{ display: "flex", alignItems: "center", gap: 11, padding: "12px 13px", borderRadius: 13, border: `1.5px solid ${on ? A : C.line}`, background: on ? `${A}0D` : "#fff", cursor: "pointer", textAlign: "left", fontFamily: "inherit" }}>
                <span style={{ flex: 1, minWidth: 0, fontSize: 13, fontWeight: 800, color: C.ink }}>{p.name}</span>
                {on ? <span style={{ width: 22, height: 22, borderRadius: "50%", background: A, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Check size={13} color="#fff" strokeWidth={3} /></span> : <span style={{ width: 20, height: 20, borderRadius: "50%", border: `2px solid ${C.line}`, flexShrink: 0 }} />}
              </button>
            );
          })}
        </div>
      </div>

      <div style={{ borderTop: `1px solid ${C.line}`, padding: "12px 16px 16px", background: "#fff" }}>
        <button disabled={!ready} onClick={() => { const r = { patient: patient.trim(), hospital: hosp.name, reason: proc.name, ccp: DOC_SUMMARY_CCP }; onRefer && onRefer(r); setDone(r); }} style={{ width: "100%", padding: "14px", borderRadius: 13, border: "none", background: ready ? A : C.canvas, color: ready ? "#fff" : C.faint, fontSize: 14.5, fontWeight: 800, cursor: ready ? "pointer" : "not-allowed", fontFamily: "inherit" }}>{ready ? "Send referral & case summary" : "Add patient, hospital & procedure"}</button>
      </div>
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════════
   DOCTOR → PATIENT SERVICE REFERRALS
   Doctor recommends any app service (test/scan/nurse/home care/…) to a
   recently-seen patient. Patient sees it in a "Recommended by your Doctor"
   section on home AND receives a bot message in the doctor chat.
   Backed by the `service_referrals` table + realtime (see backend.ts).      */
/* ══════════════════════════════════════════════════════════════════════════
   SURGERY TEAM BOOKING (Hub) — book a full OT team in one broadcast.
   Mirrors IT team's real tables: surgery_bookings + surgery_booking_roles
   (per-role first-accept-wins). Demo store simulates assembly; production
   swaps to the existing surgery.ts hooks — same field names.               */
const SURGERY_ROLES = {
  surgeon: { label: "Surgeon", emoji: "🔪", fee: 15000 },
  anaesthetist: { label: "Anaesthetist", emoji: "💉", fee: 8000 },
  obstetrician: { label: "Obstetrician", emoji: "🤰", fee: 14000 },
  paediatrician: { label: "Paediatrician", emoji: "👶", fee: 6000 },
  ot_technician: { label: "OT Technician", emoji: "🛠️", fee: 2500 },
  scrub_nurse: { label: "Scrub Nurse", emoji: "🧤", fee: 2000 },
  intensivist: { label: "Intensivist (ICU)", emoji: "🫁", fee: 9000 },
  radiographer: { label: "Radiographer / C-arm", emoji: "🩻", fee: 3000 },
};
const SURGERY_PRESETS = [
  { name: "C-section", emoji: "👶", roles: ["obstetrician", "anaesthetist", "paediatrician", "ot_technician", "scrub_nurse"], blood: true, units: 2 },
  { name: "Normal Delivery", emoji: "🍼", roles: ["obstetrician", "paediatrician", "scrub_nurse"], blood: false, units: 0 },
  { name: "Appendectomy", emoji: "🔪", roles: ["surgeon", "anaesthetist", "ot_technician"], blood: false, units: 0 },
  { name: "Fracture / Ortho", emoji: "🦴", roles: ["surgeon", "anaesthetist", "ot_technician", "radiographer"], blood: false, units: 0 },
  { name: "Cataract", emoji: "👁️", roles: ["surgeon", "anaesthetist", "scrub_nurse"], blood: false, units: 0 },
  { name: "Emergency Trauma", emoji: "🚨", roles: ["surgeon", "anaesthetist", "ot_technician", "scrub_nurse", "intensivist"], blood: true, units: 4 },
  { name: "Angioplasty / Stenting", emoji: "🩸", roles: ["surgeon", "anaesthetist", "radiographer", "ot_technician", "scrub_nurse"], blood: true, units: 2 },
  { name: "Cosmetic / Reconstructive Surgery", emoji: "💉", roles: ["surgeon", "anaesthetist", "ot_technician", "scrub_nurse"], blood: false, units: 0 },
];
const SURGERY_PROVIDER_POOL = {
  surgeon: [{ name: "Dr. Prakash Joshi", eta: 22 }, { name: "Dr. Meera Kulkarni", eta: 31 }],
  anaesthetist: [{ name: "Dr. Sameer Bhosale", eta: 18 }, { name: "Dr. Neha Deshpande", eta: 26 }],
  obstetrician: [{ name: "Dr. Anjali Wagh", eta: 20 }, { name: "Dr. Ritu Jain", eta: 29 }],
  paediatrician: [{ name: "Dr. Kiran Patil", eta: 24 }, { name: "Dr. Alok Nair", eta: 33 }],
  ot_technician: [{ name: "Suresh Kamble", eta: 15 }, { name: "Vijay Salunkhe", eta: 21 }],
  scrub_nurse: [{ name: "Sister Mary Thomas", eta: 17 }, { name: "Sister Pooja More", eta: 23 }],
  intensivist: [{ name: "Dr. Rohan Shetty", eta: 28 }, { name: "Dr. Farah Khan", eta: 35 }],
  radiographer: [{ name: "Ganesh Pawar", eta: 19 }, { name: "Amit Jadhav", eta: 27 }],
};
const SURGERY_STORE = {
  bookings: [], roles: [], listeners: new Set(), _timers: [],
  createBooking(input, roleKeys) {
    const id = "sb-" + Math.random().toString(36).slice(2, 9);
    const roleFees = input.role_fees || {};
    this.bookings = [{ id, facility_id: "hub-demo", status: "broadcasting", created_at: Date.now(), ...input }, ...this.bookings];
    roleKeys.forEach(rk => {
      this.roles = [...this.roles, {
        id: "sr-" + Math.random().toString(36).slice(2, 9), booking_id: id, role: rk,
        assigned_to: null, provider_name: null, eta_min: null, fee: roleFees[rk] ?? (SURGERY_ROLES[rk]?.fee || 0), status: "pending", accepted_at: null
      }];
    });
    this._emit(); return id;
  },
  acceptRole(roleId, providerName) {
    this.roles = this.roles.map(r => r.id === roleId && r.status === "pending"
      ? { ...r, status: "accepted", provider_name: providerName, assigned_to: "me", eta_min: r.eta_min ?? 20, accepted_at: Date.now() } : r);
    this._checkComplete(); this._emit();
  },
  cancelBooking(id) {
    this.bookings = this.bookings.map(b => b.id === id ? { ...b, status: "cancelled" } : b);
    this.roles = this.roles.map(r => r.booking_id === id && r.status === "pending" ? { ...r, status: "declined" } : r);
    this._emit();
  },
  simulate(bookingId) {
    const pend = this.roles.filter(r => r.booking_id === bookingId && r.status === "pending");
    pend.forEach((r, i) => {
      const t = setTimeout(() => {
        const pool = SURGERY_PROVIDER_POOL[r.role] || [{ name: "Dr. On-call", eta: 25 }];
        const p = pool[Math.floor(Math.random() * pool.length)];
        this.roles = this.roles.map(x => x.id === r.id && x.status === "pending"
          ? { ...x, status: "accepted", provider_name: p.name, eta_min: p.eta, accepted_at: Date.now() } : x);
        this._checkComplete(); this._emit();
      }, 1800 + i * 2100);
      this._timers.push(t);
    });
  },
  _checkComplete() {
    this.bookings = this.bookings.map(b => {
      if (b.status !== "broadcasting") return b;
      const rs = this.roles.filter(r => r.booking_id === b.id);
      return rs.length && rs.every(r => r.status === "accepted") ? { ...b, status: "confirmed" } : b;
    });
  },
  _emit() { this.listeners.forEach(fn => { try { fn(); } catch (e) { } }); },
  subscribe(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); },
};
function useSurgeryStore() {
  const [, force] = React.useState(0);
  React.useEffect(() => SURGERY_STORE.subscribe(() => force(n => n + 1)), []);
  return SURGERY_STORE;
}

