const AI_QUICK = ["Chest pain", "Fever and cold", "Back pain", "Skin rash", "Stomach ache", "Feeling anxious"];

// Server-side voice dictation — records via MediaRecorder, transcribes via Lovable AI Gateway,
// then appends the transcript to the chat input. Works in browsers without SpeechRecognition (iOS Safari).
function VoiceDictateButton({ onTranscript, disabled }) {
  const [recording, setRecording] = useState(false);
  const [busy, setBusy] = useState(false);
  const mediaRef = useRef(null);
  const chunksRef = useRef([]);
  const streamRef = useRef(null);

  const stop = useCallback(() => { try { mediaRef.current && mediaRef.current.state !== "inactive" && mediaRef.current.stop(); } catch (e) { } }, []);
  useEffect(() => () => { stop(); try { streamRef.current && streamRef.current.getTracks().forEach(t => t.stop()); } catch (e) { } }, [stop]);

  const toggle = useCallback(async () => {
    if (disabled) return;
    if (recording) { stop(); return; }
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") { alert("Voice recording is not supported in this browser."); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mime = MediaRecorder.isTypeSupported("audio/webm") ? "audio/webm" : (MediaRecorder.isTypeSupported("audio/mp4") ? "audio/mp4" : "");
      const mr = mime ? new MediaRecorder(stream, { mimeType: mime }) : new MediaRecorder(stream);
      chunksRef.current = [];
      mr.ondataavailable = (e) => { if (e.data && e.data.size > 0) chunksRef.current.push(e.data); };
      mr.onstop = async () => {
        setRecording(false);
        try { streamRef.current && streamRef.current.getTracks().forEach(t => t.stop()); } catch (e) { }
        const blob = new Blob(chunksRef.current, { type: mr.mimeType || "audio/webm" });
        if (blob.size < 200) { return; }
        setBusy(true);
        try {
          const b64 = await new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(String(r.result).split(",")[1] || ""); r.onerror = () => reject(r.error); r.readAsDataURL(blob); });
          const { text } = await transcribeAudio({ data: { audioBase64: b64, mimeType: mr.mimeType || "audio/webm" } });
          if (text && text.trim()) onTranscript(text.trim());
          else alert("Could not hear that — please try again or type instead.");
        } catch (err) {
          alert((err && err.message) || "Could not transcribe — please type instead.");
        } finally { setBusy(false); }
      };
      mr.start();
      mediaRef.current = mr;
      setRecording(true);
    } catch (e) {
      alert("Microphone permission was denied.");
    }
  }, [disabled, recording, stop, onTranscript]);

  const bg = recording ? "#DC2626" : (busy ? "#C4D0CC" : "#FFEDD5");
  const color = recording || busy ? "#FFFFFF" : "#EA580C";
  return (
    <button type="button" onClick={toggle} disabled={disabled || busy} title={recording ? "Tap to stop" : "Dictate with voice"}
      style={{ width: 42, height: 42, borderRadius: 12, flexShrink: 0, border: "none", cursor: disabled || busy ? "default" : "pointer", background: bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <Mic size={17} color={color} />
    </button>
  );
}


function AIChatOverlay({ messages, onSend, onClose, loading, onBook, emergency, onOpenHistory }) {
  const [input, setInput] = useState("");
  const [isListening, setIsListening] = useState(false);
  const [liveText, setLiveText] = useState("");
  const bottomRef = useRef(null);
  const recogRef = useRef(null);
  const finalRef = useRef("");
  const ac = emergency ? C.emerg : C.primary;

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, loading]);

  // cleanup on unmount
  useEffect(() => () => { recogRef.current?.abort?.(); }, []);

  const startListening = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert("Voice not supported in this browser — please type your symptoms."); return; }
    if (isListening) { recogRef.current?.stop(); return; }
    finalRef.current = "";
    const r = new SR();
    r.lang = "en-IN"; r.continuous = false; r.interimResults = true;
    r.onstart = () => { setIsListening(true); setLiveText(""); };
    r.onresult = (e) => {
      const txt = Array.from(e.results).map(x => x[0].transcript).join("");
      setLiveText(txt);
      if (e.results[e.results.length - 1].isFinal) { finalRef.current = txt; setLiveText(txt); }
    };
    r.onerror = () => { setIsListening(false); setLiveText(""); };
    r.onend = () => {
      setIsListening(false);
      setLiveText("");
      const spoken = finalRef.current.trim();
      finalRef.current = "";
      if (spoken) { setInput(""); onSend(spoken, { viaVoice: true }); }
    };
    r.start();
    recogRef.current = r;
  }, [isListening, onSend]);

  const [inputSource, setInputSource] = useState("keyboard");
  const send = useCallback(() => {
    const t = input.trim(); if (!t || loading) return;
    onSend(t, { viaVoice: inputSource === "voice" });
    setInput(""); setInputSource("keyboard");
  }, [input, loading, onSend, inputSource]);

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 60, background: C.surface, display: "flex", flexDirection: "column" }}>

      {/* ── Header ─────────────────────────────────────────────── */}
      <div style={{ padding: "12px 14px 10px", display: "flex", alignItems: "center", gap: 10, borderBottom: `1px solid ${C.line}`, flexShrink: 0 }}>
        <div style={{ width: 38, height: 38, borderRadius: 11, background: "linear-gradient(135deg,#EA580C,#F97316)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Sparkles size={19} color="white" />
        </div>
        <div style={{ flex: 1 }}>
          <p style={{ fontWeight: 800, color: C.ink, fontSize: 15, margin: 0 }}>AI Health Assistant</p>
          <p style={{ color: C.faint, fontSize: 11, margin: "1px 0 0" }}>Powered by Claude — triage suggestions only</p>
        </div>
        {onOpenHistory && (
          <button onClick={onOpenHistory} title="View saved AI history"
            style={{ padding: "6px 10px", borderRadius: 99, background: "#FFEDD5", color: "#9A3412", border: "none", cursor: "pointer", fontWeight: 800, fontSize: 11, display: "flex", alignItems: "center", gap: 4 }}>
            <Clock size={12} /> History
          </button>
        )}
        <button onClick={onClose} style={{ width: 32, height: 32, borderRadius: "50%", background: C.canvas, border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={15} style={{ color: C.sub }} /></button>
      </div>

      {/* ── Messages ───────────────────────────────────────────── */}
      <div style={{ flex: 1, overflowY: "auto", padding: "14px 14px 6px", scrollbarWidth: "none" }}>
        {messages.map((msg, i) => {
          const isUser = msg.role === "user";
          return (
            <div key={i} style={{ display: "flex", justifyContent: isUser ? "flex-end" : "flex-start", marginBottom: 14, alignItems: "flex-end", gap: 8 }}>
              {!isUser && <div style={{ width: 30, height: 30, borderRadius: "50%", background: "linear-gradient(135deg,#EA580C,#F97316)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginBottom: 2 }}><Sparkles size={14} color="white" /></div>}
              <div style={{ maxWidth: "80%" }}>
                <div style={{ background: isUser ? `linear-gradient(135deg,${ac},${ac}CC)` : C.canvas, color: isUser ? "white" : C.ink, borderRadius: isUser ? "18px 18px 4px 18px" : "4px 18px 18px 18px", padding: "10px 13px", fontSize: 13.5, lineHeight: 1.55 }}>{msg.displayText}</div>
                {msg.emergency && <EmergencyPanel onBook={onBook} flagLabel={msg.emergency.label} />}
                {msg.rec && (msg.rec.urgent ? <EmergencyPanel onBook={onBook} flagLabel={msg.rec.reason || "Emergency care advised"} /> : <RecCard rec={msg.rec} onBook={onBook} />)}
              </div>
            </div>
          );
        })}
        {loading && (
          <div style={{ display: "flex", alignItems: "flex-end", gap: 8, marginBottom: 14 }}>
            <div style={{ width: 30, height: 30, borderRadius: "50%", background: "linear-gradient(135deg,#EA580C,#F97316)", display: "flex", alignItems: "center", justifyContent: "center" }}><Sparkles size={14} color="white" /></div>
            <div style={{ background: C.canvas, borderRadius: "4px 18px 18px 18px", padding: "12px 16px", display: "flex", gap: 5, alignItems: "center" }}>
              {[0, 1, 2].map(j => (<span key={j} style={{ width: 7, height: 7, borderRadius: "50%", background: C.faint, animation: `pulse 1.2s ${j * 0.22}s infinite`, display: "inline-block" }} />))}
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      {/* ── Quick chips (first turn) ────────────────────────────── */}
      {messages.length <= 1 && !loading && (
        <div style={{ padding: "0 14px 8px", display: "flex", gap: 6, flexWrap: "wrap", flexShrink: 0 }}>
          {["Chest pain", "Fever and cold", "Back pain", "Skin rash", "Stomach ache", "Feeling anxious"].map(s => (
            <button key={s} onClick={() => onSend(s)} style={{ padding: "6px 11px", borderRadius: 99, border: `1.5px solid ${C.line}`, background: C.surface, color: C.sub, fontSize: 11.5, fontWeight: 600, cursor: "pointer", fontFamily: "'Plus Jakarta Sans',sans-serif" }}>{s}</button>
          ))}
        </div>
      )}

      {/* ── Voice + text input area ─────────────────────────────── */}
      <div style={{ padding: "14px 18px 20px", borderTop: `1px solid ${C.line}`, display: "flex", flexDirection: "column", alignItems: "center", gap: 10, background: "white", flexShrink: 0 }}>

        {/* Live transcript bubble */}
        {(isListening || liveText) && (
          <div style={{ width: "100%", background: "#FFF7ED", borderRadius: 12, padding: "9px 14px", textAlign: "center", border: "1.5px solid #FDBA74" }}>
            <p style={{ color: "#EA580C", fontSize: 13, fontWeight: 600, margin: 0, lineHeight: 1.4 }}>
              {liveText || "Listening… speak now"}
            </p>
          </div>
        )}

        {/* Big Mic button */}
        <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center", padding: "12px 0 4px" }}>
          {/* Pulse rings */}
          {isListening && [1, 2, 3].map(n => (
            <div key={n} style={{ position: "absolute", width: 88 + n * 28, height: 88 + n * 28, borderRadius: "50%", border: "2.5px solid #FF5A3C", animation: `voicePulse 1.8s ${(n - 1) * 0.35}s ease-out infinite`, pointerEvents: "none" }} />
          ))}
          <button
            onClick={startListening}
            disabled={loading}
            style={{
              width: 88, height: 88, borderRadius: "50%", border: "none",
              cursor: loading ? "default" : "pointer",
              background: isListening
                ? "linear-gradient(135deg,#FF5A3C,#FF8466)"
                : "linear-gradient(135deg,#EA580C,#F97316)",
              display: "flex", alignItems: "center", justifyContent: "center",
              boxShadow: isListening
                ? "0 10px 34px -6px rgba(255,90,60,.75)"
                : "0 10px 34px -6px rgba(234,88,12,.7)",
              transform: isListening ? "scale(1.06)" : "scale(1)",
              transition: "all .3s cubic-bezier(.2,.8,.2,1)",
              flexShrink: 0,
            }}>
            {/* Mic SVG */}
            <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="9" y="2" width="6" height="11" rx="3" fill="white" fillOpacity="0.25" />
              <path d="M19 10c0 3.87-3.13 7-7 7s-7-3.13-7-7" />
              <line x1="12" y1="19" x2="12" y2="22" />
              <line x1="8" y1="22" x2="16" y2="22" />
            </svg>
          </button>
        </div>

        {/* Mic label */}
        <p style={{ color: isListening ? "#FF5A3C" : "#EA580C", fontSize: 12, fontWeight: 700, margin: 0, letterSpacing: ".02em", transition: "color .3s" }}>
          {loading ? "Thinking…" : isListening ? "Tap again to stop" : "Tap mic to speak"}
        </p>

        {/* OR divider */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, width: "100%" }}>
          <div style={{ flex: 1, height: 1, background: C.line }} />
          <span style={{ color: C.faint, fontSize: 11, fontWeight: 600 }}>or type below</span>
          <div style={{ flex: 1, height: 1, background: C.line }} />
        </div>

        {/* Text input row */}
        <div style={{ display: "flex", gap: 8, width: "100%" }}>
          <input value={input} onChange={e => { setInput(e.target.value); setInputSource("keyboard"); }}
            onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } }}
            placeholder="Type your symptoms…" disabled={loading || isListening}
            style={{ flex: 1, background: C.canvas, border: `1.5px solid ${input.trim() && !loading ? "#EA580C" : C.line}`, borderRadius: 12, padding: "9px 11px", fontSize: 13, color: C.ink, outline: "none", fontFamily: "'Plus Jakarta Sans',sans-serif", transition: "border-color .15s" }} />
          <VoiceDictateButton disabled={loading || isListening} onTranscript={(t) => { setInput(prev => prev ? prev + " " + t : t); setInputSource("voice"); }} />
          <button onClick={send} disabled={!input.trim() || loading || isListening}
            style={{ width: 42, height: 42, borderRadius: 12, flexShrink: 0, border: "none", cursor: (!input.trim() || loading || isListening) ? "default" : "pointer", background: (!input.trim() || loading || isListening) ? "#C4D0CC" : "linear-gradient(135deg,#EA580C,#F97316)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <Navigation size={17} color="white" />
          </button>
        </div>

      </div>
    </div>
  );
}




/* ═══ AI HISTORY OVERLAY ═══════════════════════════════════════════════
   Lists the signed-in user's saved AI triage / voice / report summaries.
   Supports opening a full detail view, sharing via a public link, and delete.
─────────────────────────────────────────────────────────────────────── */
function AIHistoryOverlay({ onClose }) {
  const [items, setItems] = useState(null); // null=loading, []=empty
  const [err, setErr] = useState("");
  const [activeId, setActiveId] = useState(null);
  const [detail, setDetail] = useState(null);
  const [busyId, setBusyId] = useState(null);

  const load = useCallback(async () => {
    setErr("");
    try {
      const rows = await listAiHistory();
      setItems(rows || []);
    } catch (e) {
      setErr((e && e.message) || "Sign in to view your saved AI history.");
      setItems([]);
    }
  }, []);
  useEffect(() => { load(); }, [load]);

  const open = async (id) => {
    setActiveId(id); setDetail(null);
    try {
      const row = await getAiHistoryItem({ data: { id } });
      setDetail(row);
    } catch (e) { setDetail({ error: (e && e.message) || "Could not load." }); }
  };

  const share = async (id, currentTok) => {
    setBusyId(id);
    try {
      const r = await toggleShareAiHistory({ data: { id, share: !currentTok } });
      const tok = r?.share_token || null;
      setItems(prev => (prev || []).map(it => it.id === id ? { ...it, share_token: tok } : it));
      if (tok) {
        const link = `${window.location.origin}/shared/ai/${tok}`;
        try { await navigator.clipboard.writeText(link); toast("Share link copied"); }
        catch (_e) { toast("Share link ready: " + link); }
      } else { toast("Sharing turned off"); }
    } catch (e) { toast((e && e.message) || "Could not update sharing"); }
    finally { setBusyId(null); }
  };

  const remove = async (id) => {
    if (!confirm("Delete this saved AI summary?")) return;
    setBusyId(id);
    try {
      await deleteAiHistory({ data: { id } });
      setItems(prev => (prev || []).filter(it => it.id !== id));
      if (activeId === id) { setActiveId(null); setDetail(null); }
      toast("Deleted");
    } catch (e) { toast((e && e.message) || "Could not delete"); }
    finally { setBusyId(null); }
  };

  const KIND_META = {
    triage: { label: "Triage", color: "#EA580C", bg: "#FFEDD5" },
    voice: { label: "Voice", color: "#7C3AED", bg: "#EDE9FE" },
    report: { label: "Report", color: "#0EA5E9", bg: "#E0F2FE" },
  };

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 70, background: C.surface, display: "flex", flexDirection: "column" }}>
      <div style={{ padding: "12px 14px", display: "flex", alignItems: "center", gap: 10, borderBottom: `1px solid ${C.line}`, flexShrink: 0 }}>
        <div style={{ width: 36, height: 36, borderRadius: 11, background: "#FFEDD5", display: "flex", alignItems: "center", justifyContent: "center" }}><Sparkles size={17} style={{ color: "#EA580C" }} /></div>
        <div style={{ flex: 1 }}>
          <p style={{ fontWeight: 800, color: C.ink, fontSize: 15, margin: 0 }}>{activeId ? "Saved AI summary" : "Saved AI history"}</p>
          <p style={{ color: C.faint, fontSize: 11, margin: "1px 0 0" }}>{activeId ? "Review or share this summary" : "Triage · Voice · Report analyses"}</p>
        </div>
        {activeId && <button onClick={() => { setActiveId(null); setDetail(null); }} style={{ padding: "6px 10px", borderRadius: 8, background: C.canvas, border: "none", cursor: "pointer", fontWeight: 700, fontSize: 11, color: C.sub }}>Back</button>}
        <button onClick={onClose} style={{ width: 32, height: 32, borderRadius: "50%", background: C.canvas, border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={15} style={{ color: C.sub }} /></button>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 14 }}>
        {!activeId && items === null && <p style={{ color: C.faint, fontSize: 12 }}>Loading…</p>}
        {!activeId && items && items.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 20px" }}>
            <p style={{ color: C.sub, fontSize: 13, fontWeight: 700, margin: 0 }}>No saved summaries yet</p>
            <p style={{ color: C.faint, fontSize: 11.5, marginTop: 6 }}>{err || "Chat with the AI, analyze a report, or use voice — they'll show up here."}</p>
          </div>
        )}
        {!activeId && items && items.length > 0 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {items.map(it => {
              const meta = KIND_META[it.kind] || { label: it.kind, color: "#334155", bg: "#F1F5F9" };
              const when = new Date(it.created_at).toLocaleString();
              return (
                <div key={it.id} style={{ padding: "10px 12px", borderRadius: 12, background: C.canvas, border: `1px solid ${C.line}`, display: "flex", flexDirection: "column", gap: 6 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <span style={{ fontSize: 10, fontWeight: 800, padding: "2px 8px", borderRadius: 99, background: meta.bg, color: meta.color }}>{meta.label}</span>
                    <span style={{ fontSize: 10.5, color: C.faint }}>{when}</span>
                    {it.share_token && <span style={{ fontSize: 10, color: "#065F46", fontWeight: 700 }}>· Shared</span>}
                  </div>
                  <p onClick={() => open(it.id)} style={{ margin: 0, fontSize: 13, fontWeight: 700, color: C.ink, cursor: "pointer" }}>{it.title || "Untitled"}</p>
                  <div style={{ display: "flex", gap: 6, marginTop: 2 }}>
                    <button onClick={() => open(it.id)} style={{ padding: "5px 10px", borderRadius: 8, border: "none", background: "#0EA5E9", color: "#fff", fontWeight: 800, fontSize: 11, cursor: "pointer" }}>Open</button>
                    <button onClick={() => share(it.id, it.share_token)} disabled={busyId === it.id} style={{ padding: "5px 10px", borderRadius: 8, border: "none", background: it.share_token ? "#DC2626" : "#7C3AED", color: "#fff", fontWeight: 800, fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", gap: 4 }}>
                      {it.share_token ? (<><X size={11} /> Stop</>) : (<><Share2 size={11} /> Share</>)}
                    </button>
                    <button onClick={() => remove(it.id)} disabled={busyId === it.id} style={{ marginLeft: "auto", padding: "5px 8px", borderRadius: 8, border: "none", background: "#FEE2E2", color: "#B91C1C", fontWeight: 800, fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", gap: 4 }}>
                      <Trash2 size={11} />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {activeId && !detail && <p style={{ color: C.faint, fontSize: 12 }}>Loading…</p>}
        {activeId && detail?.error && <p style={{ color: "#B91C1C", fontSize: 12 }}>{detail.error}</p>}
        {activeId && detail && !detail.error && (
          <AIHistoryDetail row={detail} onShare={() => share(detail.id, detail.share_token)} busy={busyId === detail.id} />
        )}
      </div>
    </div>
  );
}

function AIHistoryDetail({ row, onShare, busy }) {
  const FLAG = { normal: "#16A34A", high: "#DC2626", low: "#2563EB", critical: "#7C3AED" };
  const payload = row.payload || {};
  const when = new Date(row.created_at).toLocaleString();
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <p style={{ margin: 0, fontSize: 15, fontWeight: 800, color: C.ink, flex: 1 }}>{row.title}</p>
        <button onClick={onShare} disabled={busy} style={{ padding: "6px 10px", borderRadius: 8, border: "none", background: row.share_token ? "#DC2626" : "#7C3AED", color: "#fff", fontWeight: 800, fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", gap: 5 }}>
          {row.share_token ? (<><X size={11} /> Stop sharing</>) : (<><Share2 size={11} /> Copy share link</>)}
        </button>
      </div>
      <p style={{ margin: 0, fontSize: 11, color: C.faint }}>{when}</p>
      {row.share_token && (
        <div style={{ padding: "8px 10px", borderRadius: 8, background: "#ECFDF5", border: "1px solid #A7F3D0", fontSize: 11, color: "#065F46", display: "flex", alignItems: "center", gap: 6 }}>
          <Share2 size={12} /> Anyone with the link can view this summary.
        </div>
      )}

      {(row.kind === "triage" || row.kind === "voice") && Array.isArray(payload.messages) && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {payload.messages.map((m, i) => (
            <div key={i} style={{ padding: "9px 11px", borderRadius: 10, background: m.role === "user" ? "#EFF6FF" : C.canvas, border: `1px solid ${m.role === "user" ? "#BFDBFE" : C.line}` }}>
              <p style={{ margin: "0 0 3px", fontSize: 9.5, fontWeight: 800, textTransform: "uppercase", color: C.faint }}>{m.role === "user" ? "You" : "MedAI"}</p>
              <p style={{ margin: 0, fontSize: 12.5, color: C.ink, whiteSpace: "pre-wrap" }}>{m.content}</p>
            </div>
          ))}
          {payload.rec && (
            <div style={{ padding: "9px 11px", borderRadius: 10, background: "#ECFDF5", border: "1px solid #A7F3D0" }}>
              <p style={{ margin: 0, fontSize: 12, color: "#065F46" }}><b>Recommendation:</b> {payload.rec.name || payload.rec.id} — {payload.rec.reason}</p>
            </div>
          )}
        </div>
      )}

      {row.kind === "report" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {payload.narration && (
            <div style={{ padding: "10px 12px", borderRadius: 10, background: "#FFEDD5" }}>
              <p style={{ margin: "0 0 4px", fontSize: 10, fontWeight: 800, color: "#9A3412" }}>AI SUMMARY</p>
              <p style={{ margin: 0, fontSize: 12, color: "#7C2D12", lineHeight: 1.5 }}>{payload.narration}</p>
            </div>
          )}
          {(payload.rows || []).map((r, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 10, background: C.canvas, border: `1px solid ${C.line}` }}>
              <span style={{ width: 8, height: 8, borderRadius: "50%", background: FLAG[r.flag] || "#ccc" }} />
              <span style={{ flex: 1, fontSize: 12.5, fontWeight: 700, color: C.ink }}>{r.analyte}</span>
              <span style={{ fontSize: 12.5, fontWeight: 800, color: FLAG[r.flag] || C.ink }}>{r.value} {r.unit}</span>
              <span style={{ fontSize: 10, color: C.faint }}>ref {r.refLow}{"\u2013"}{r.refHigh}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}





